import{_ as o,a0 as u,w as l,s as d,ao as i,I as p,x as s,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Ubuntu 23.10 将引入安全增强的 PPA | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 23.10 将引入安全增强的 PPA | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 23.10 将引入安全增强的 PPA | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 23.10 将引入安全增强的 PPA | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs","title":"Ubuntu 23.10 将引入安全增强的 PPA","tag":"202305","desc":""},"relativePath":"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs.md","filePath":"[post].md"}'),r={name:"202305/20230517.1 ⭐️ Ubuntu 23.10 To Bring Security Enhanced PPAs.md"};function g(P,t,b,c,h,m){const e=u("Link");return l(),d("div",null,[t[16]||(t[16]=i('<h1 id="ubuntu-23-10-将引入安全增强的-ppa" tabindex="-1">Ubuntu 23.10 将引入安全增强的 PPA <a class="header-anchor" href="#ubuntu-23-10-将引入安全增强的-ppa" aria-label="Permalink to “Ubuntu 23.10 将引入安全增强的 PPA”">​</a></h1><blockquote><p>Ubuntu 23.10 正在修改 PPA 的管理方式。</p></blockquote><p><img src="https://news.itsfoss.com/content/images/size/w1304/2023/05/ubuntu-better-ppa-management.png" alt="ubuntu 23.10 ppa"></p><p>Ubuntu 的升级不断地增强功能并添加安全修复程序。但是，很少见到一些核心机制的更改。</p><p>在 Ubuntu 23.10 中，PPA 的功能得到了改进。至少，你在终端中看到警告会更少。</p><p>这是什么意思呢？让我详细说明一下。</p><h3 id="gpg-密钥问题" tabindex="-1">GPG 密钥问题 <a class="header-anchor" href="#gpg-密钥问题" aria-label="Permalink to “GPG 密钥问题”">​</a></h3><p>传统上，PPA 和其他外部存储库是通过 <code>/etc/apt/sources.list.d/</code> 中的 <code>.list</code> 来源列表文件进行管理的。此外，还有一个关联的 GPG 密钥环被放在 <code>/etc/apt/trusted.gpg.d</code> 中。</p><p>这被认为是一个潜在的安全问题，因为 GPG 密钥是在系统级别上添加的。</p><p>怎么回事？想象一下，你为存储库 A 添加密钥以获取包 AA，并从存储库 B 获取包 BB。你的系统将很乐意接受用存储库 A 的密钥签名的 BB 包。因为它无法将密钥与其各自的包关联起来。</p><p>这是个问题，对吧？这种旧机制正在逐步淘汰。现在，GPG 密钥信息将添加到外部存储库本身的 <code>sources.list</code> 中。这样，GPG 密钥将只接受其对应存储库的软件包。</p><p>现有的 Ubuntu 用户可能已经遇到了使用 <code>/etc/apt/trusted.gpg.d</code> 中的旧方法添加 GPG 密钥时出现的 <code>apt-key is deprecated</code> 警告。</p>',12)),p("p",null,[t[1]||(t[1]=s("以下是旧的 ",-1)),a(e,{href:"https://itsfoss.com/adding-external-repositories-ubuntu/?ref=news.itsfoss.com"},{default:n(()=>[...t[0]||(t[0]=[s("添加外部存储库",-1)])]),_:1}),t[2]||(t[2]=s(" 的方法的示例：",-1))]),t[17]||(t[17]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install apt-transport-https curl</span></span>
<span class="line"><span>curl -sS https://dl.yarnpkg.com/debian/pubkey.gpg | sudo apt-key add -</span></span>
<span class="line"><span>sudo sh -c &#39;echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; &gt;&gt; /etc/apt/sources.list.d/yarn.list&#39;</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install yarn</span></span></code></pre></div><h3 id="ppa-将使用新的-gpg-密钥机制" tabindex="-1">PPA 将使用新的 GPG 密钥机制 <a class="header-anchor" href="#ppa-将使用新的-gpg-密钥机制" aria-label="Permalink to “PPA 将使用新的 GPG 密钥机制”">​</a></h3><p>现在，PPA 与添加外部存储库略有不同。在这里，你不需要手动导入 GPG 密钥并将其添加到 <code>/etc/apt/trusted.gpg.d</code> 目录中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:dr-akulavich/lighttable</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install lighttable-installer</span></span></code></pre></div><p><strong>直到现在</strong>，所有事情都由 PPA 机制自己处理，与 PPA 相关联的 GPG 密钥会自动添加到 <code>/etc/apt/trusted.gpg.d</code> 目录中。用户在这里不需要做任何事情。</p><p>在 Ubuntu 23.10 中，引入了一种新的方法。</p><p>现在，PPA 将作为 deb822 格式的 <code>.sources</code> 文件添加，其中密钥直接嵌入文件的 <code>Signed-By</code> 字段中。</p><p>使用这种方法，可以获得以下一些优点：</p><ul><li>当删除存储库时，相关的密钥也会被删除。</li><li>PPA 与其密钥之间一一对应。没有安全问题。</li></ul><p>在揭示这一消息的邮件列表中也提到：</p><blockquote><p>该密钥专门用于特定的 PPA，无法用于其他存储库（与旧的存放所有存储库的源列表的 <code>trusted.gpg.d</code> 不同）。其他密钥不能用于签署该 PPA。</p></blockquote><p>总的来说，新的 PPA 版本将减少 “Key is stored in legacy trusted.gpg keyring” 和 “Manage keyring files in trusted.gpg.d instead” 警告。</p><p>我认为 Ubuntu 应该早些时候就引入这个改变，但迟到总比没有好。 😊</p><p>你对 Ubuntu 处理 PPA 的这个新改变有什么想法？请让我知道你的想法。</p><hr>`,15)),p("p",null,[t[4]||(t[4]=s("via: ",-1)),a(e,{href:"https://news.itsfoss.com/ubuntu-23-10-set-to-let-you-easily-manage-ppas-while-enhancing-security/"},{default:n(()=>[...t[3]||(t[3]=[s("https://news.itsfoss.com/ubuntu-23-10-set-to-let-you-easily-manage-ppas-while-enhancing-security/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=s("作者：",-1)),a(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[5]||(t[5]=[s("Ankush Das",-1)])]),_:1}),t[9]||(t[9]=s(" 选题：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...t[6]||(t[6]=[s("lkxed",-1)])]),_:1}),t[10]||(t[10]=s(" 译者：ChatGPT 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[s("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[s("LCTT",-1)])]),_:1}),t[14]||(t[14]=s(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[s("Linux中国",-1)])]),_:1}),t[15]||(t[15]=s(" 荣誉推出",-1))])])}const T=o(r,[["render",g]]);export{A as __pageData,T as default};
